Hypothesis: Lowering the initial Muon momentum from 0.85 to 0.80 will make early matrix updates more responsive and strictly improve validation BPB. Category: optimization. Parent: experiment 61 / attempt 48. Exact diff: --- results/candidates/autoresearch-seed42-20260723/0048-train.py	2026-07-23 08:50:14.000000000 +0000
+++ queue/autoresearch-seed42-20260723/0049-train.py	2026-07-23 09:00:56.000000000 +0000
@@ -526,7 +526,7 @@

 def get_muon_momentum(step):
     frac = min(step / 300, 1)
-    return (1 - frac) * 0.85 + frac * 0.95
+    return (1 - frac) * 0.80 + frac * 0.95

 def get_weight_decay(progress):
     return WEIGHT_DECAY * (1 - progress)

